create or replace package body t001_pricing as
  function line_amount(
    p_qty          in number,
    p_unit_price   in number,
    p_discount_pct in number default 0
  ) return number is
  begin
    -- The discount should be applied to the total price (qty * unit_price).
    -- If p_discount_pct is 10 (for 10%), the multiplier should be (1 - 0.10) = 0.90.
    -- The original code was: p_qty * p_unit_price * (1 - nvl(p_discount_pct, 0))
    -- If p_discount_pct is 10, it calculates: qty * price * (1 - 10) = qty * price * -9.
    -- Assuming p_discount_pct is provided as a percentage value (e.g., 10 for 10%), we must divide it by 100.
    return round(p_qty * p_unit_price * (1 - nvl(p_discount_pct, 0) / 100), 2);
  end line_amount;
end t001_pricing;
